@log_decorator
def select_image(imgItem):
    return click_item(Xvi_MainPage.intuity_XVI_Default_Database_Image_List, imgItem)

@log_decorator
def open_Edit_Image():
    if squishtest.waitForObjectExists(Xvi_MainPage.edit_Image_Pane).enabled:
        common.left_click_object(Xvi_MainPage.edit_Image_Pane)
    else:
        print("Edit Image is not ready")

@log_decorator
def click_Delete_Image():
    common.left_click_object(Xvi_MainPage.delete_Image_Pane)

@log_decorator
def delete_image(confirm: bool):
    click_Delete_Image()
    acknowledge_Delete_Image(confirm)

@log_decorator
def acknowledge_Delete_Image(confirm: bool):
    if squishtest.waitForObject(Xvi_MainPage.intuity_XVI_Default_Database_XVI_Are_you_sure_you_want_to_delete_this_image_and_all_the_associated_data_Reconstruction_Registration_Label):
        if confirm:
            common.left_click_object(Xvi_MainPage.intuity_XVI_Default_Database_XVI_Yes_Button)
        else:
            common.left_click_object(Xvi_MainPage.intuity_XVI_Default_Database_XVI_No_Button)

