@log_decorator
def get_image_item_by_index(index: int):
    imgList = get_list_items(Xvi_MainPage.intuity_XVI_Default_Database_Image_List)
    count = len(imgList)
    if count > 0 and index < count:
        return imgList[index]

@log_decorator
def get_current_image_item():
    ps = get_children(Xvi_MainPage.intuity_XVI_Default_Database_Image_List)
    for p in ps:
        if p.type == "ListItem" and p.selected and hasattr(p, "text"):
            return p.text
    return ""

@log_decorator
def parse_image_item(imgItem: str):
    '''
    Parse imgItem to partial ImageInfo data
    '''
    imgData = ImageInfo()
    info_parts = imgItem.split(" " * 3)
    if len(info_parts) < 4:
        return imgData
    imgData.date = info_parts[0]
    imgData.time = info_parts[1]
    imgData.type = info_parts[2]
    rest, rec = info_parts[3].split(" ")
    imgData.reference_image = 'R' in rest  #RMsegRev Rec
    imgData.imrt_segment = ''.join(char for char in rest if char.isdigit()) or "0"
    imgData.movie = 'M' in rest
    imgData.review_status = next((char for char in rest if char in ['/', '!', 'X', ' ']), '')
    imgData.reconstruction = rec
    return imgData

@log_decorator
def format_image_item(image: ImageInfo):
    '''
    Format a Image list item for given ImageInfo data
    '''
    sml_sep = " "
    col_sep = " " * 3  # Column separator
    date = image.date
    time = image.time
    image_type = image.type
    ref = "R" if image.reference_image else ""
    mov = "M" if image.frames != "" and int(image.frames) > 1 else ""
    seg = image.imrt_segment if image.imrt_segment and int(image.imrt_segment) > 0 else ""
    rev = image.review_status
    rec = image.reconstruction
    imgItem = f"{date}{col_sep}{time}{col_sep}{image_type}{col_sep}{ref}{mov}{seg}{rev}{sml_sep}{rec}"
    return imgItem
